                "cells": cells,
                "size": len(cells),
                "minr": min(rs),
                "maxr": max(rs),
                "minc": min(cs),
                "maxc": max(cs),
            })

    if not components:
        return out

    # Main object = largest non-background component
    main = max(components, key=lambda comp: comp["size"])
    minr, maxr, minc, maxc = main["minr"], main["maxr"], main["minc"], main["maxc"]

    # For every other singleton, connect it to the rectangle if aligned
    for comp in components:
        if comp is main:
            continue
        if comp["size"] != 1:
            continue

        r, c = comp["cells"][0]
        color = comp["color"]

        # Horizontal connection
        if minr <= r <= maxr:
            if c < minc:
                for y in range(c, minc):
                    out[r][y] = color
            elif c > maxc:
                for y in range(maxc + 1, c + 1):
                    out[r][y] = color

        # Vertical connection
        elif minc <= c <= maxc:
            if r < minr:
                for x in range(r, minr):
                    out[x][c] = color
            elif r > maxr:
                for x in range(maxr + 1, r + 1):
                    out[x][c] = color

    return out

